{
  "aktywnosci": [
    {
      "tytul": "Leśne liście – zabawa sensoryczna",
      "opis": "Przygotuj koszyk z prawdziwymi liśćmi (klon, dąb, brzoza) oraz ich wydrukami lub rysunkami. Dzieci po kolei sięgają do koszyka, wyciągają liść, nazywają jego kolor (czerwony, żółty, pomarańczowy, brązowy) i próbują dopasować do obrazka. Nauczyciel pomaga w nazywaniu odcieni i pokazuje, że liście są różne nie tylko kolorem, ale też kształtem."
    },
    {
      "tytul": "Taniec jesiennych liści",
      "opis": "Nauczyciel rozdaje dzieciom po dwa liście z papieru (lub prawdziwe, suche) i puszcza spokojną, instrumentalną muzykę. Dzieci naśladują opadanie liści – kręcą się, kucają, wirują z rękami w górze. Gdy muzyka cichnie, zbierają liście z podłogi do koszyka. Zabawa rozwija koordynację i wrażliwość na rytm."
    },
    {
      "tytul": "Wycinamy i układamy jesienny obrazek",
      "opis": "Dzieci dostają kontury liści (klon, dąb, kasztanowiec) narysowane na kolorowym papierze (żółtym, pomarańczowym, czerwonym) – wycinają je, a potem przyklejają na dużą kartkę, tworząc wspólny jesienny dywan. Nauczyciel pomaga przy wycinaniu i zachęca do nazywania kolorów. Gotowa praca ozdabia salę."
    }
  ]
}
